}


def slot_endpoints(slot):
    out = []
    def walk(value, tokens):
        if not tokens:
            out.append(value)
            return
        head, rest = tokens[0], tokens[1:]
        if head == "*":
            for child in value:
                walk(child, rest)
        elif isinstance(value, dict) and head in value:
            walk(value[head], rest)
    for pointer in ENDPOINT_POINTERS[slot["request"]["operation"]]:
        walk(slot, pointer.split("/"))
    return out


def subject_index(slots, resolution):
    rows = {}
    for row in resolution:
        if row["state"] == "resolved":
            rows[canonical(row["endpoint"])] = {"subjectId": subject_id(row["endpoint"]), "endpoint": copy.deepcopy(row["endpoint"])}
    for slot in slots:
        for endpoint in slot_endpoints(slot):
            rows[canonical(endpoint)] = {"subjectId": subject_id(endpoint), "endpoint": copy.deepcopy(endpoint)}
    return sorted(rows.values(), key=lambda r: r["subjectId"].encode())


def page_law(context, item_count, size, bounds, position=0):
    """Owner page/count law for one page of a logical graph operation (query-projection-contract.v3 sections 5-6).
    position: canonical-prefix offset of this page (0 for a first page; the bound cursor position for a continuation).
    - produced-item law (:136): the operation's produced prefix has producedItems units; remaining units are owed (lower-bound);
    - totalItems qualified by countBasis (:146): exact => every unit was produced; lower-bound => the produced prefix; so totalItems == producedItems;
    - completeness (:140) is complete AND exact; full pages are truncated-page (truncated=false); truncated iff truncated-bound;
    - a page is the slice [position, position+items) of the produced prefix; a cursor continues exactly at position+items;
      no cursor means the page set ends here, so position+items == producedItems.
    Returns None when lawful, else the violated clause. Owed work only arises when a produced or visited cap was reached."""
    coverage, basis, cursor = context["traversalCoverage"], context["countBasis"], context.get("nextCursor")
    total, produced, visited = context["totalItems"], context["producedItems"], context["visitedNodes"]
    capped = produced == bounds["maxItemsPerOperation"] or visited == bounds["maxVisitedNodes"]
    end = position + item_count
    if context["truncated"] != (coverage == "truncated-bound"):
        return "truncated iff truncated-bound"
    if produced > bounds["maxItemsPerOperation"] or visited > bounds["maxVisitedNodes"]:
        return "counts exceed effective caps"
    if total != produced:
        return "totalItems must equal producedItems (exact: all units produced; lower-bound: the produced prefix)"
    if item_count > size or end > produced:
        return "page exceeds its size or the produced prefix"
    if basis == "lower-bound" and not capped:
        return "lower-bound without a reached produced/visited cap"
    if basis == "exact" and coverage == "truncated-bound":
        return "truncated-bound owes work: countBasis must be lower-bound"
    if coverage == "complete" and (basis != "exact" or cursor is not None):
        return "complete requires countBasis exact and no cursor"
    if cursor is not None:
        if coverage == "complete" or item_count != size or end >= produced:
            return "a continued page must be full and leave produced rows for the cursor"
    else:
        if end != produced:
            return "the page set ends without a cursor: every produced row must be embedded by this page"
        if coverage == "truncated-page":
            return "truncated-page requires a cursor"
    return None


def continuation_for(context):
    """Host continuation derived only from the owner answer: a page set is complete only for an exact complete answer."""
    if "nextCursor" in context:
        return "not-embedded"
    if context["traversalCoverage"] == "complete" and context["countBasis"] == "exact":
        return "complete-page-set"
    return "operation-truncated-no-continuation"

