        requirement_text[row_id] = sha(section.encode())
    assert "Bind metrics and test reachability to the exact universe/identity and show unknown values" in inventory_md
    assert "a blank cell is not a global no-dependency proof" in inventory_md and "Replace browser entry-point heuristics" in inventory_md
    native_md = (arch / "docs/v2/contracts/product-v1/native-evidence.md").read_text()
    for sentence in ("explicit configuration wins and sets `entryPoints.source=explicit`", "**FR-5** A recognizer version change is a Plan-visible change.",
